const item = $input.first();

if (!item.binary || Object.keys(item.binary).length === 0) {
  throw new Error('No binary audio data received from Telegram. Make sure "Get Voice File" downloaded the voice file.');
}

// Telegram usually stores the file under the "data" property; fall back to whatever key is present.
const binaryKey = item.binary.data ? 'data' : Object.keys(item.binary)[0];
const binary = item.binary[binaryKey];

binary.fileName = 'voice.ogg';
binary.mimeType = 'audio/ogg';

// Ensure the downstream Whisper node reads the binary from the "data" field.
if (binaryKey !== 'data') {
  item.binary.data = binary;
  delete item.binary[binaryKey];
}

return [item];

const transcript = $input.first().json.text;
const trigger = $('Voice Message Trigger').first().json.message;

return [{
  json: {
    transcript,
    chatId: trigger.chat.id,
    userId: trigger.from.id,
    userName: trigger.from.first_name || 'Customer'
  }
}];

