={{ JSON.stringify({
  model: "llama-3.1-8b-instant",
  temperature: 0,
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: "You classify messages sent to CBox, a crypto wallet app's support line. Return ONLY valid JSON, no markdown, no commentary, in this exact shape: {\"intent\": \"faq|transaction_issue|account_kyc|wallet_security|trading_swap\", \"sentiment\": \"neutral|frustrated|angry\", \"security_risk\": true|false, \"confidence\": 0.0}. Set security_risk to true if the message mentions: unauthorized or unrecognized transactions, missing/stolen funds, a suspected phishing attempt, someone asking the user for their seed phrase or private key, suspicious app behavior, or the user believing their wallet is compromised. Intent categories: faq (general how-to or policy questions with no reference to the user's own account, e.g. 'how long does KYC take', 'what networks are supported', 'what is slippage' - these should be faq even if they mention KYC, transactions, or trading by name); transaction_issue (the user is asking about the status of their own specific stuck/pending/failed transaction, or their own deposit/withdrawal not showing); account_kyc (the user is asking about their own verification status, their own account limits, or their own account access - not general KYC policy); wallet_security (2FA setup, device management, or a security_risk situation); trading_swap (a specific swap the user made failed, or gas fee/slippage/token support questions tied to their own trade). Rule of thumb: if the question could be answered the same way for any user without looking up their account, classify it as faq." },
    { role: "user", content: $json.transcript }
  ]
}) }}

