const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { intent: 'faq', sentiment: 'neutral', security_risk: false, confidence: 0 };
}

let prior;
try {
  prior = $('Extract Transcript (Voice)').first().json;
} catch (e) {
  prior = $('Extract Transcript (Text)').first().json;
}

return [{
  json: {
    ...prior,
    intent: parsed.intent,
    sentiment: parsed.sentiment,
    security_risk: !!parsed.security_risk,
    confidence: parsed.confidence
  }
}];

const rows = $input.all();
const now = Date.now();

const activeLock = rows.some(r => {
  if (!r.json.escalatedAt) return false;
  const escalatedAt = new Date(r.json.escalatedAt).getTime();
  return (now - escalatedAt) < 30 * 60 * 1000; // 30 min window
});

const context = $('Parse Classification JSON').item.json;

return [{ json: { ...context, isLocked: activeLock } }];

