let context;
try { context = $('Parse Classification JSON').item.json; } catch (e) { context = {}; }

let replyText;
try { replyText = $('Extract Reply Text').item.json.replyText; } catch (e) { replyText = null; }

const escalated = context.sentiment === 'angry' || context.sentiment === 'frustrated' || context.security_risk === true;

return [{
  json: {
    timestamp: new Date().toISOString(),
    chatId: context.chatId,
    userName: context.userName,
    transcript: context.transcript,
    intent: context.intent,
    sentiment: context.sentiment,
    securityRisk: context.security_risk,
    escalated,
    reply: escalated ? 'Escalated to a human specialist; sent the user a holding voice reply.' : replyText
  }
}];

